import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('names the missing required property in a rejection ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      namesRequiredProperty: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesRequiredProperty: true,
    });
  });
});

